and then in the source code ﬁle: 
#include "list.h" 
#include "reduce.h" 
II This works fine, but iterating over a list like this is 
II fairly slow. See if you can speed it up! 
int ReduceFunction::reduce( const List &list ) const { 
int result = identity(); 
for( size t p = 0; p < list.length(); ++p ) { 
result = function( result, list.value( p ) ); 
} 
return result; 
} 
int SumReduce::function( int x, int y ) const { 
return x + y; 
} 
