43: /** COPIED FROM LIST.H FOR REFERENCE
44:  *
45:  * struct node{
46:  *  int val;
47:  *  struct node* next;
48:  *};
49:  */
50: 
51: /** remove_matches:
52:  * removes all list entries that match the supplied value
53:  * for example calling remove_matches on a list with {1, 3, 3, 4, 2, 5}
54:  * and a value of 3 should yield { 1, 4, 2, 5 }.
55:  *
56:  * remove_matches should have a void return type
57:  *
58:  * note that when an element is added to a list, the node to store it is created
59:  * on the heap
60:  *
61:  * once you've implemented remove_matches, insert a call to
62:  * your function in the proper place
63:  **/
64: 
65:  void removeMatches( node * list, int valToRemove ) {
66: 
67:   if (list == nullptr) {
68:     return;
69:   }
70:   while( list && list->val == valToRemove) {
71:     node *temp  = list;
72:     list = list->next;
73:     free(temp);
74:   }
75:   if ( list == nullptr ) {
76:     return;
77:   }
78:   node *prev = list;
79:   node *curr = prev->next;
80: 
81:   while( curr != nullptr ) {
82:     if (curr->val == valToRemove) {
83:       node *temp  = curr;
84:       prev->next = curr->next;
85:       curr = curr->next;
86:       free(temp);
87:     } else {
88:       prev = curr;
89:       curr = curr->next;
90:     }
91: 
92:   }
93:  }
